import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"04.7 案例题专攻：UML 建模","description":"","frontmatter":{},"headers":[],"relativePath":"04-面向对象与设计模式/07-案例题专攻.md","filePath":"04-面向对象与设计模式/07-案例题专攻.md"}'),g={name:"04-面向对象与设计模式/07-案例题专攻.md"};function e(d,t,u,a,l,q){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_04-7-案例题专攻-uml-建模" tabindex="-1">04.7 案例题专攻：UML 建模 <a class="header-anchor" href="#_04-7-案例题专攻-uml-建模" aria-label="Permalink to &quot;04.7 案例题专攻：UML 建模&quot;">​</a></h1><p>案例题的形态固定为「<strong>文字说明 + 挖空的图（用例图/类图/顺序图/通信图/活动图/状态图之一）</strong>」，常配 3 个小问。三个固定套路如下。</p><h3 id="套路一-补用例图——参与者、用例、include-extend" tabindex="-1">套路一：补用例图——参与者、用例、include/extend <a class="header-anchor" href="#套路一-补用例图——参与者、用例、include-extend" aria-label="Permalink to &quot;套路一：补用例图——参与者、用例、include/extend&quot;">​</a></h3><ol><li><strong>参与者</strong>：名词且&quot;谁在使用系统/系统服务谁&quot;（读者、管理员、外部系统如支付网关）；</li><li><strong>用例</strong>：系统为参与者完成的一件完整的事（动词短语：借书、还书、缴费）；</li><li><strong>挖空补关系</strong>：句子里&quot;必须先/一定要&quot;→ include；&quot;如果…就/可选&quot;→ extend；两种&quot;某类参与者…&quot;→ 用例泛化。</li></ol><p><strong>从&quot;用例详细描述&quot;里挖答案</strong>（近真题的新形态）：题目给的往往是一段标准格式的描述——<strong>参与者 / 典型事件流（1、2、3…）/ 备选事件流（2a、4a…）</strong>。读法三条：</p><ul><li><strong>参与者</strong>直接抄（原文写了&quot;参与者：读者&quot;）；</li><li><strong>典型事件流的每一步</strong>对应顺序图/通信图里的一条消息，<strong>步骤序号 = 消息顺序</strong>；</li><li><strong>备选事件流 → extend 的来源</strong>（如&quot;4a 读者要借的书无法外借 → 告知本书无法借阅&quot;就是&quot;告知无法借阅&quot;这个扩展用例）。</li></ul><h3 id="套路二-补类图——名词变类、关系按语义套-方法按事件流找" tabindex="-1">套路二：补类图——名词变类、关系按语义套，方法按事件流找 <a class="header-anchor" href="#套路二-补类图——名词变类、关系按语义套-方法按事件流找" aria-label="Permalink to &quot;套路二：补类图——名词变类、关系按语义套，方法按事件流找&quot;">​</a></h3><ol><li><strong>类名</strong>：说明中的<strong>核心名词</strong>（读者、图书、借阅记录）——注意填空题要求&quot;<strong>用图中给出的英文词汇</strong>&quot;，所以要把中文名词与英文类名对应上（读者 = Patron、图书 = Book、目录 = Catalog）；</li><li><strong>属性</strong>：说明里&quot;要记录的信息&quot;（书号、书名、定价）；</li><li><strong>方法（补 M1、M2…）</strong>：<strong>从事件流的动词里找</strong>，且<strong>要匹配调用者与接收者</strong>——如&quot;根据图书目录中的图书ID确认该书可以借阅&quot;这一步，主语是目录对象 → 方法就是目录提供的 <code>find(bookID)</code>／<code>getForCheckOut(id)</code>；&quot;判断读者身份&quot;→ 读者对象的 <code>isFaculty()</code>；</li><li><strong>多重性</strong>：按 3.1 的&quot;<strong>逐端问</strong>&quot;法填写；</li><li><strong>关联类</strong>：多对多时中间挂<strong>关联类</strong>（学生—课程之间挂&quot;选课记录&quot;——与第 2 课 m:n 转关系模式同构）。</li></ol><p><strong>判&quot;哪个方法属于哪个类&quot;的通用办法</strong>：看<strong>动作的宾语归谁管</strong>——&quot;查书&quot;问的是图书/目录 → 方法落在这两个类上；&quot;生成借阅记录&quot;要落到借阅记录或会话控制类上；&quot;通知读者应还日期&quot;落到读者或通知类上。</p><h3 id="套路三-补顺序图-通信图-状态图-活动图——按说明的顺序与事件照搬" tabindex="-1">套路三：补顺序图/通信图/状态图/活动图——按说明的顺序与事件照搬 <a class="header-anchor" href="#套路三-补顺序图-通信图-状态图-活动图——按说明的顺序与事件照搬" aria-label="Permalink to &quot;套路三：补顺序图/通信图/状态图/活动图——按说明的顺序与事件照搬&quot;">​</a></h3><ol><li><strong>顺序图挖消息</strong>：按说明句子的<strong>先后顺序</strong>填消息名（从上到下 = 时间先后），注意返回消息（虚线箭头）也要填；</li><li><strong>通信图挖序号</strong>：序号体现调用层次（<code>1</code>、<code>1.1</code>、<code>1.1.2</code>），<strong>先定第一个调用，再补嵌套</strong>；</li><li><strong>状态图挖状态/事件</strong>：状态 = 名词（空闲/占线），转换线上标<strong>事件</strong>（题干会说&quot;当…时进入…&quot;）；起点实心圆、终点带圈圆；</li><li><strong>活动图挖动作/条件</strong>：动作 = 动词短语，菱形出口标<strong>监护表达式</strong>（题干会说&quot;如果…则…否则…&quot;）。</li></ol><h3 id="套路四-设计模式小问-可以采用何种设计模式-简要说明原因" tabindex="-1">套路四：设计模式小问（&quot;可以采用何种设计模式？简要说明原因&quot;） <a class="header-anchor" href="#套路四-设计模式小问-可以采用何种设计模式-简要说明原因" aria-label="Permalink to &quot;套路四：设计模式小问（&quot;可以采用何种设计模式？简要说明原因&quot;）&quot;">​</a></h3><p>这是 <strong>3 分题</strong>，答题<strong>必须两段：模式名 + 原因</strong>（只写名字通常拿不满）。原因要<strong>用题目原话 + 原则名</strong>，模板如下：</p><blockquote><p>可以采用<strong>策略（Strategy）模式</strong>。理由：题库中的规则（制度）会不断扩充和调整，属于<strong>一族可互相替换的算法</strong>；采用策略模式把每种规则封装成独立的策略类，由上下文按需注入，<strong>新增规则时只需增加新的策略类，不必修改原有代码</strong>，符合<strong>开放-封闭原则</strong>。</p></blockquote><p><strong>识别抓手（题干 → 模式）</strong>：</p><table tabindex="0"><thead><tr><th>题干出现</th><th>答案模式</th></tr></thead><tbody><tr><td>&quot;可灵活扩充/调整的一系列规则、算法，可互相替换&quot;</td><td><strong>策略</strong></td></tr><tr><td>&quot;状态改变时通知所有相关对象/订阅者&quot;</td><td><strong>观察者</strong></td></tr><tr><td>&quot;创建过程复杂、分步骤，且表示可不同&quot;</td><td><strong>构建器</strong></td></tr><tr><td>&quot;系统只能有一个××（如全局配置、唯一编号生成器）&quot;</td><td><strong>单例</strong></td></tr><tr><td>&quot;要接入已有接口不兼容的第三方/旧系统&quot;</td><td><strong>适配器</strong></td></tr><tr><td>&quot;需要在不修改类的前提下增加新操作&quot;</td><td><strong>访问者</strong></td></tr><tr><td>&quot;对象行为随自身状态变化而变化&quot;</td><td><strong>状态</strong></td></tr><tr><td>&quot;需要支持撤销/重做、操作排队&quot;</td><td><strong>命令</strong></td></tr><tr><td>&quot;多步骤处理，每个处理者只处理自己管的部分，其余往下传&quot;</td><td><strong>职责链</strong></td></tr></tbody></table><p><strong>应试动作</strong>：这一问<strong>先写模式名再写理由</strong>，理由必含「<strong>新增/变化时只需加新类、不必改原有代码</strong>」这类功能点，并<strong>点名原则</strong>（开放-封闭 / 依赖倒置 / 单一职责）。给分点是<strong>关键词</strong>，不是文采。</p><hr>',18)])])}const h=o(g,[["render",e]]);export{c as __pageData,h as default};
